/* गट-क सराव: चालू घडामोडी (धडे + प्रश्न)
 * हा भाग वेगळ्या फाइलमध्ये आहे, म्हणजे दर महिन्याला फक्त ही फाइल बदलून चालू घडामोडी अद्ययावत करता येतात.
 * धडा: {id,s:"ca",t,imp,pyq,d,sn,tr,src:[[नाव,url],...]}
 * प्रश्न: [प्रश्न, [4 पर्याय], बरोबर पर्याय (0–3), स्पष्टीकरण, {i, v, src, y, u}]
 *   questions.js प्रमाणेच रचना: i = कायमचा प्रश्न-क्रमांक (उदा. "ca3-007"; बदलू नका, पुन्हा वापरू नका; प्रश्न काढायचा असल्यास x:1 द्या)
 *   v:"s" = src मधील स्रोताशी जुळवले · src = स्रोताची लिंक · y = वर्ष किंवा "pyq" · u:1 = अलीकडची/अनिश्चित माहिती, तपासा
 * नवीन प्रश्न जोडताना त्या धड्याचा पुढचा i द्या आणि शक्यतो अधिकृत स्रोत (PIB, AIR, शासन संकेतस्थळ, RBI, nobelprize.org) src मध्ये जोडा. */
